using System;
using System.IO;
using System.Text;

public class ReportGenerator
{
    public void GenerateReport(SummaryReport report, bool exportToCsv = false, string csvFilePath = null)
    {
        // Existing functionality: Output summary report to console
        Console.WriteLine("Report Summary:");
        Console.WriteLine(report.ToString());

        // New functionality: Export to CSV if requested
        if (exportToCsv)
        {
            if (string.IsNullOrEmpty(csvFilePath))
            {
                csvFilePath = "report.csv";
            }

            try
            {
                using (var writer = new StreamWriter(csvFilePath, false, Encoding.UTF8))
                {
                    // Write CSV header
                    writer.WriteLine("Field,Value");

                    // Write report data as CSV rows
                    // Assuming SummaryReport has properties that can be iterated or a method to get key-value pairs
                    // For demonstration, we assume report has a method GetProperties() returning a dictionary or similar
                    // If not, you may need to adapt this part based on the actual structure of SummaryReport

                    // Example: If SummaryReport implements IEnumerable<KeyValuePair<string, string>>
                    foreach (var kvp in report.GetProperties())
                    {
                        // Escape values if they contain commas or quotes
                        string value = kvp.Value.Replace("\"", "\"\"");
                        writer.WriteLine($"\"{kvp.Key}\",\"{value}\"");
                    }
                }

                Console.WriteLine($"Report exported to CSV: {csvFilePath}");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error exporting report to CSV: {ex.Message}");
            }
        }
    }
}

